def _clip_xy(target_xy: np.ndarray, center_xy: np.ndarray, max_radius: float = 0.30) -> np.ndarray:
    delta = target_xy - center_xy
    dist = float(np.linalg.norm(delta))
    if dist <= max_radius or dist == 0.0:
        return target_xy
    return center_xy + delta * (max_radius / dist)

def guidance(state: State) -> tuple[str, CartesianProposal]:
    observation = state.current
    tip = np.asarray(observation.tip[:3], dtype=float)
    target = np.array(observation.object_pose[:3], dtype=float)
    quat = state.initial.tip[3:]
    if state.instruction == "take lid off the saucepan":
