        else:
            stage, gripper = "approach", observation.gripper_command
        return stage, CartesianProposal(target=tuple(target), quaternion=quat, gripper=gripper)

    # button task
    radial = state.radial_dist
    if radial > 0.34:
        # far buttons: first descend less and press from above at edge-reachable xy
        base_xy = np.asarray(state.initial.tip[:2], dtype=float)
